import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import Application from '../Application';
import UIEventBus from '../UI/EventBus';
import EventEmitter from './EventEmitter';
import { disposeOnce, disposeScene } from './Dispose';
export default class Resources extends EventEmitter {
    constructor(sources) {
        super();
        this.disposed = false;
        this.released = new WeakSet();
        this.sources = sources;
        this.items = { texture: {}, cubeTexture: {}, gltfModel: {}, audio: {} };
        this.toLoad = this.sources.length;
        this.loaded = 0;
        this.application = new Application();
        this.loading = this.application.loading;
        this.setLoaders();
        this.startLoading();
    }
    setLoaders() {
        this.loaders = {
            gltfLoader: new GLTFLoader(),
            textureLoader: new THREE.TextureLoader(),
            cubeTextureLoader: new THREE.CubeTextureLoader(),
            audioLoader: new THREE.AudioLoader(),
        };
    }
    startLoading() {
        const failed = () => { if (!this.disposed)
            UIEventBus.dispatch('resourceLoadError', {}); };
        // Load each source
        for (const source of this.sources) {
            if (source.type === 'gltfModel') {
                this.loaders.gltfLoader.load(source.path, (file) => {
                    this.sourceLoaded(source, file);
                }, undefined, failed);
            }
            else if (source.type === 'texture') {
                this.loaders.textureLoader.load(source.path, (file) => {
                    file.encoding = THREE.sRGBEncoding;
                    this.sourceLoaded(source, file);
                }, undefined, failed);
            }
            else if (source.type === 'cubeTexture') {
                this.loaders.cubeTextureLoader.load(source.path, (file) => {
                    this.sourceLoaded(source, file);
                }, undefined, failed);
            }
            else if (source.type === 'audio') {
                this.loaders.audioLoader.load(source.path, (buffer) => {
                    this.sourceLoaded(source, buffer);
                }, undefined, failed);
            }
        }
    }
    sourceLoaded(source, file) {
        if (this.disposed) {
            this.release(file, this.released);
            return;
        }
        this.items[source.type][source.name] = file;
        this.loaded++;
        this.loading.trigger('loadedSource', [
            source.name,
            this.loaded,
            this.toLoad,
        ]);
        if (this.loaded === this.toLoad) {
            this.trigger('ready');
        }
    }
    release(file, seen) {
        if (file instanceof THREE.Texture)
            disposeOnce(file, seen);
        const scene = file.scene;
        if (scene instanceof THREE.Object3D)
            disposeScene(scene, seen);
    }
    dispose(seen = new WeakSet()) {
        if (this.disposed)
            return;
        this.disposed = true;
        this.released = seen;
        this.off('ready');
        Object.values(this.items).forEach(items => Object.values(items).forEach(file => this.release(file, seen)));
        this.items = { texture: {}, cubeTexture: {}, gltfModel: {}, audio: {} };
    }
}
